    /// <summary>
    /// OASIS provider for ENS (Ethereum Name Service).
    /// ENS names → Avatars. Subdomains → Holons.
    /// Uses ENS Subgraph GraphQL for reads.
    /// </summary>
    public class ENSOASIS : OASISStorageProviderBase, IOASISStorageProvider, IOASISNETProvider
    {
        private readonly HttpClient _httpClient;
        private bool _isActivated;
        private const string SubgraphUrl = "https://api.thegraph.com/subgraphs/name/ensdomains/ens";

        public ENSOASIS()
        {
            _httpClient = new HttpClient();
            _httpClient.DefaultRequestHeaders.Add("Accept", "application/json");
            ProviderName = "ENSOASIS";
            ProviderDescription = "Ethereum Name Service (ENS) Provider";
            ProviderType = new EnumValue<ProviderType>(Core.Enums.ProviderType.ENSOASIS);
            ProviderCategory = new EnumValue<ProviderCategory>(Core.Enums.ProviderCategory.StorageAndNetwork);
            ProviderCategories.Add(new EnumValue<ProviderCategory>(Core.Enums.ProviderCategory.Blockchain));
        }

        public override async Task<OASISResult<bool>> ActivateProviderAsync()
        {
            var result = new OASISResult<bool>();
            try
            {
                var query = new { query = "{ _meta { block { number } } }" };
                var response = await _httpClient.PostAsJsonAsync(SubgraphUrl, query);
                if (response.IsSuccessStatusCode) { _isActivated = true; result.Result = true; result.Message = "ENSOASIS activated."; }
                else OASISErrorHandling.HandleError(ref result, $"ENSOASIS: Subgraph health check failed ({response.StatusCode}).");
            }
            catch (Exception ex) { result.Exception = ex; OASISErrorHandling.HandleError(ref result, ex.Message); }
            return result;
        }
        public override OASISResult<bool> ActivateProvider() => ActivateProviderAsync().Result;
        public override async Task<OASISResult<bool>> DeActivateProviderAsync() { _isActivated = false; return new OASISResult<bool>(true); }
        public override OASISResult<bool> DeActivateProvider() => DeActivateProviderAsync().Result;

        public override async Task<OASISResult<IAvatar>> LoadAvatarByProviderKeyAsync(string providerKey, int version = 0)
        {
            var result = new OASISResult<IAvatar>();
            try
            {
                var ensName = providerKey.ToLower().TrimEnd('/');
                var query = new { query = $"{{ domains(where: {{name: \"{ensName}\"}}) {{ id name owner {{ id }} resolvedAddress {{ id }} parent {{ name }} createdAt }} }}" };
                var response = await _httpClient.PostAsJsonAsync(SubgraphUrl, query);
                if (response.IsSuccessStatusCode)
                {
                    var body = await response.Content.ReadFromJsonAsync<JsonElement>();
                    var domains = body.TryGetProperty("data", out var d) && d.TryGetProperty("domains", out var dm) ? dm : default;
                    if (domains.ValueKind == JsonValueKind.Array && domains.GetArrayLength() > 0)
                    {
                        var domain = domains[0];
                        var avatar = new Avatar();
                        avatar.Username = ensName;
                        avatar.MetaData["ens_name"] = ensName;
                        avatar.MetaData["ens_owner"] = domain.TryGetProperty("owner", out var o) && o.TryGetProperty("id", out var oid) ? oid.GetString() : "";
                        avatar.MetaData["ens_resolved_address"] = domain.TryGetProperty("resolvedAddress", out var ra) && ra.ValueKind != JsonValueKind.Null && ra.TryGetProperty("id", out var raid) ? raid.GetString() : "";
                        avatar.MetaData["ens_created_at"] = domain.TryGetProperty("createdAt", out var ca) ? ca.ToString() : "";
                        result.Result = avatar;
                    }
                    else OASISErrorHandling.HandleError(ref result, $"ENSOASIS: ENS name '{ensName}' not found.");
                }
                else OASISErrorHandling.HandleError(ref result, $"ENSOASIS: Subgraph query failed ({response.StatusCode}).");
            }
            catch (Exception ex) { result.Exception = ex; OASISErrorHandling.HandleError(ref result, ex.Message); }
            return result;
        }
        public override OASISResult<IAvatar> LoadAvatarByProviderKey(string providerKey, int version = 0) => LoadAvatarByProviderKeyAsync(providerKey, version).Result;

        public override async Task<OASISResult<IEnumerable<IHolon>>> LoadHolonsForParentAsync(string providerKey, HolonType type = HolonType.All, bool loadChildren = true, bool recursive = true, int maxChildDepth = 0, int curentChildDepth = 0, bool continueOnError = true, bool loadChildrenFromProvider = false, int version = 0)
        {
            var result = new OASISResult<IEnumerable<IHolon>>(); var holons = new List<IHolon>();
            try
            {
                var parentName = providerKey.ToLower().TrimEnd('/');
                var query = new { query = $"{{ domains(where: {{parent_: {{name: \"{parentName}\"}}}}, first: 1000) {{ id name owner {{ id }} createdAt }} }}" };
                var response = await _httpClient.PostAsJsonAsync(SubgraphUrl, query);
                if (response.IsSuccessStatusCode)
                {
                    var body = await response.Content.ReadFromJsonAsync<JsonElement>();
                    var domains = body.TryGetProperty("data", out var d) && d.TryGetProperty("domains", out var dm) ? dm : default;
                    if (domains.ValueKind == JsonValueKind.Array)
                        foreach (var domain in domains.EnumerateArray())
                        {
                            var holon = new Holon();
                            holon.Name = domain.TryGetProperty("name", out var n) ? n.GetString() : "";
                            holon.MetaData["ens_name"] = holon.Name;
                            holon.MetaData["ens_owner"] = domain.TryGetProperty("owner", out var o) && o.TryGetProperty("id", out var oid) ? oid.GetString() : "";
                            holon.MetaData["ens_created_at"] = domain.TryGetProperty("createdAt", out var ca) ? ca.ToString() : "";
                            holons.Add(holon);
                        }
                    result.Result = holons;
                }
                else OASISErrorHandling.HandleError(ref result, $"ENSOASIS: Subgraph query failed ({response.StatusCode}).");
            }
            catch (Exception ex) { result.Exception = ex; OASISErrorHandling.HandleError(ref result, ex.Message); }
            return result;
        }
        public override OASISResult<IEnumerable<IHolon>> LoadHolonsForParent(string providerKey, HolonType type = HolonType.All, bool loadChildren = true, bool recursive = true, int maxChildDepth = 0, int curentChildDepth = 0, bool continueOnError = true, bool loadChildrenFromProvider = false, int version = 0)
            => LoadHolonsForParentAsync(providerKey, type, loadChildren, recursive, maxChildDepth, curentChildDepth, continueOnError, loadChildrenFromProvider, version).Result;

        public override async Task<OASISResult<IHolon>> LoadHolonAsync(string providerKey, bool loadChildren = true, bool recursive = true, int maxChildDepth = 0, bool continueOnError = true, bool loadChildrenFromProvider = false, int version = 0)
        {
            var result = new OASISResult<IHolon>();
            try
            {
                var ensName = providerKey.ToLower();
                var query = new { query = $"{{ domains(where: {{name: \"{ensName}\"}}) {{ id name owner {{ id }} resolvedAddress {{ id }} createdAt }} }}" };
                var response = await _httpClient.PostAsJsonAsync(SubgraphUrl, query);
                if (response.IsSuccessStatusCode)
                {
                    var body = await response.Content.ReadFromJsonAsync<JsonElement>();
                    var domains = body.TryGetProperty("data", out var d) && d.TryGetProperty("domains", out var dm) ? dm : default;
                    if (domains.ValueKind == JsonValueKind.Array && domains.GetArrayLength() > 0)
                    {
                        var domain = domains[0];
                        var holon = new Holon();
                        holon.Name = ensName;
                        holon.MetaData["ens_name"] = ensName;
                        holon.MetaData["ens_owner"] = domain.TryGetProperty("owner", out var o) && o.TryGetProperty("id", out var oid) ? oid.GetString() : "";
                        holon.MetaData["ens_resolved_address"] = domain.TryGetProperty("resolvedAddress", out var ra) && ra.ValueKind != JsonValueKind.Null && ra.TryGetProperty("id", out var raid) ? raid.GetString() : "";
                        result.Result = holon;
                    }
                    else OASISErrorHandling.HandleError(ref result, $"ENSOASIS: ENS name '{ensName}' not found.");
                }
                else OASISErrorHandling.HandleError(ref result, $"ENSOASIS: Subgraph query failed ({response.StatusCode}).");
            }
            catch (Exception ex) { result.Exception = ex; OASISErrorHandling.HandleError(ref result, ex.Message); }
            return result;
        }
